const full = path.join(root, target)
if (!fs.existsSync(full)) {
  console.error('ABORT - ' + target + ' not found. Run this from the repo root.')
  process.exit(1)
}

const body = Buffer.from(PARTS.join(''), 'base64').toString('utf8')
if (body.indexOf('export const loader') < 0 || body.length < 20000) {
  console.error('ABORT - the new file did not arrive in one piece.')
  process.exit(1)
}

fs.mkdirSync(bak, { recursive: true })
fs.copyFileSync(full, path.join(bak, target.replace(/[\\/]/g, '_') + '.' + stamp + '.bak'))
fs.writeFileSync(full, body)

console.log('written  ' + target)
